FUNCTION_BLOCK FB_H2DRI_HBIRollerPressQuench
(* ========================================================================================= *)
(* LUMINA CYBER-PHYSICAL SYSTEMS AUTOMATION FELLOW ARCHITECTURE                            *)
(* SYSTEM: HYDROGEN DIRECT REDUCED IRON (H2-DRI) HBI PRODUCTION PLANT                       *)
(* SUBSYSTEM: HOT BRIQUETTED IRON ROLLER PRESS SYNCHRONIZATION AND INERTED PRODUCT QUENCH  *)
(* IEC 61131-3 COMPLIANT FUNCTION BLOCK ARCHITECTURE (SIL-2 / SIL-3 CAPABLE)                *)
(* ========================================================================================= *)

VAR_INPUT
    bEnable                     : BOOL;     (* System master run permissive [TRUE = Active Request] *)
    bEStopOk                    : BOOL;     (* Redundant dual-channel hardwired safety relay healthy [TRUE = OK] *)
    bN2PurgePermissive          : BOOL;     (* Seal chamber inerting positive pressure & O2 < 1.0% permissive *)
    bBreakerBarRunning          : BOOL;     (* Discharge strand breaker mechanical drive operational feedback *)
    rHydPress_A1_bar            : REAL;     (* Cylinder A hydraulic pressure transducer CH1 [bar] *)
    rHydPress_A2_bar            : REAL;     (* Cylinder A hydraulic pressure transducer CH2 [bar] *)
    rHydPress_A3_bar            : REAL;     (* Cylinder A hydraulic pressure transducer CH3 [bar] *)
    rHydPress_B1_bar            : REAL;     (* Cylinder B hydraulic pressure transducer CH1 [bar] *)
    rHydPress_B2_bar            : REAL;     (* Cylinder B hydraulic pressure transducer CH2 [bar] *)
    rHydPress_B3_bar            : REAL;     (* Cylinder B hydraulic pressure transducer CH3 [bar] *)
    rRollGap_A_mm               : REAL;     (* Floating roll linear position LVDT - Drive End Side A [mm] *)
    rRollGap_B_mm               : REAL;     (* Floating roll linear position LVDT - Operator Side B [mm] *)
    rRollSpeedActual_rpm        : REAL;     (* Dual counter-rotating briquetting roll shaft speed [rpm] *)
    rFeedScrewSpeedActual_rpm   : REAL;     (* Pre-densification vertical tapered screw feeder speed [rpm] *)
    rHDRI_FeedTemp_degC         : REAL;     (* Optical infrared dual-wavelength HDRI chute feed temperature [deg C] *)
    rQuenchWaterTempIn_degC     : REAL;     (* Closed-loop recirculating quench water header inlet temperature [deg C] *)
    rQuenchWaterFlow_m3h        : REAL;     (* Primary quench curtain electromagnetic flow transmitter [m3/h] *)
    rQuenchTankLevel_pct        : REAL;     (* Submerged quench flight conveyor tank hydro-static level [%] *)
    rForceSetpoint_kN           : REAL;     (* Total target linear compaction force setpoint [kN] *)
    rTargetRollGap_mm           : REAL;     (* Nominal briquette pocket pitch working gap setpoint [mm] *)
    rTargetExitTemp_degC        : REAL;     (* Maximum safe HBI product surface temperature at conveyor discharge [deg C] *)
    bResetFaults                : BOOL;     (* Operator manual fault acknowledgement and reset command *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* All pre-conditions satisfied, press primed and ready to compact *)
    bBriquettingActive          : BOOL;     (* High-temperature hot briquetting active closed-loop cycle *)
    bQuenchSprayActive          : BOOL;     (* Primary high-pressure quench curtain spray active *)
    rServoValve_A_mA            : REAL;     (* Cylinder A proportional electro-hydraulic servo command [4.0..20.0 mA] *)
    rServoValve_B_mA            : REAL;     (* Cylinder B proportional electro-hydraulic servo command [4.0..20.0 mA] *)
    rFeedScrewSpeedCmd_rpm      : REAL;     (* Vertical tapered screw pre-compactor VFD speed reference [rpm] *)
    rQuenchSprayValve_pct       : REAL;     (* Modulating quench water heat-exchange flow control valve [0.0..100.0 %] *)
    rQuenchConveyorSpeed_mpm    : REAL;     (* Submerged quench drag flight conveyor variable speed drive [m/min] *)
    rMeasuredCompactionForce_kN : REAL;     (* Total instantaneous calculated roll compaction force [kN] *)
    rRollTiltDelta_mm           : REAL;     (* Cross-axis roll angular skew deviation (Gap A - Gap B) [mm] *)
    rVotedPress_A_bar           : REAL;     (* Triple modular redundant 2oo3 validated pressure Cylinder A [bar] *)
    rVotedPress_B_bar           : REAL;     (* Triple modular redundant 2oo3 validated pressure Cylinder B [bar] *)
    wSystemStatusWord           : WORD;     (* Diagnostic bitfield: Operational status, interlocks & modes *)
    wAlarmCode                  : WORD;     (* Diagnostic bitfield: Active safety, process & instrument trips *)
END_VAR

VAR
    (* Sequential State Automation *)
    iState                      : INT := 0; (* Master state machine index (0..90) *)
    iPrevState                  : INT := 0;
    iDegradedMode               : INT := 0; (* Graceful degradation: 0=Nominal TMR, 1=Cyl A degraded, 2=Cyl B degraded *)

    (* 2oo3 Triple Modular Redundancy (TMR) Voting Engine Variables *)
    rDiff_A1_A2                 : REAL;
    rDiff_A2_A3                 : REAL;
    rDiff_A3_A1                 : REAL;
    bFail_A1                    : BOOL;
    bFail_A2                    : BOOL;
    bFail_A3                    : BOOL;
    rDiff_B1_B2                 : REAL;
    rDiff_B2_B3                 : REAL;
    rDiff_B3_B1                 : REAL;
    bFail_B1                    : BOOL;
    bFail_B2                    : BOOL;
    bFail_B3                    : BOOL;
    rTMR_Tolerance_bar          : REAL := 12.5; (* Discrepancy threshold for sensor divergence [bar] *)

    (* First-Order Discrete IIR Low-Pass Filter Accumulators *)
    rFiltPress_A                : REAL := 0.0;
    rFiltPress_B                : REAL := 0.0;
    rFiltGap_A                  : REAL := 15.0;
    rFiltGap_B                  : REAL := 15.0;
    rFiltHDRI_Temp              : REAL := 700.0;
    rFilterAlpha                : REAL := 0.20; (* Filter smoothing coefficient (Ts = 10ms) *)

    (* Mechanical & Cylinder Hydraulic Geometry Constants *)
    rCylinderArea_cm2           : REAL := 804.25; (* Piston diameter 320 mm effective area [cm2] *)
    rPressureToForceFactor      : REAL := 0.080425; (* F [kN] = P [bar] * Area [cm2] / 10 *)
    rMaxAllowableTilt_mm        : REAL := 0.85;   (* Critical bearing protection roll skew trip limit [mm] *)
    rWarningTilt_mm             : REAL := 0.40;   (* Active tilt correction threshold [mm] *)

    (* State-Space Dynamic Matrices for Gap Tilt & Differential Force Decoupling *)
    (* State vector x = [MeanGapError (mm), AngularTiltDeviation (mm)]^T                        *)
    (* Control input u = [MeanServoPressure (bar), DeltaServoDifferential (bar)]^T              *)
    A_mat                       : ARRAY[1..2, 1..2] OF REAL := [0.942, 0.015, 0.012, 0.938];
    B_mat                       : ARRAY[1..2, 1..2] OF REAL := [0.078, -0.012, -0.010, 0.081];
    C_mat                       : ARRAY[1..2, 1..2] OF REAL := [1.000, 0.000, 0.000, 1.000];
    K_lqr                       : ARRAY[1..2, 1..2] OF REAL := [5.250, -1.150, -1.150, 6.850];
    x_obs                       : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Observer states *)

    (* MPC Horizon & Predictive Vectors *)
    rMeanGapError               : REAL := 0.0;
    rDeltaTiltError             : REAL := 0.0;
    rMeanForceError             : REAL := 0.0;
    rCtrlEffort_Mean            : REAL := 0.0;
    rCtrlEffort_Delta           : REAL := 0.0;
    rCmdPress_A_bar             : REAL := 0.0;
    rCmdPress_B_bar             : REAL := 0.0;

    (* Feed Screw Pre-Compactor Volumetric Synchronization Ratio *)
    rFeedRatio_Base             : REAL := 3.45; (* Baseline rpm screw / rpm roll *)
    rFeedRatio_Adapted          : REAL := 3.45;
    rPressErrorIntegral         : REAL := 0.0;
    rKp_Screw                   : REAL := 0.018;
    rKi_Screw                   : REAL := 0.004;

    (* Quench Tank Thermodynamics & Heat Balance Model *)
    (* Q_thermal = m_dot_hbi * c_p_iron * (T_in - T_target)                                     *)
    (* m_dot_water = Q_thermal / (c_p_water * DeltaT_water_subboiling)                          *)
    rCp_Iron_kJ_kgK             : REAL := 0.695; (* Specific heat capacity of HDRI sponge iron *)
    rCp_Water_kJ_kgK            : REAL := 4.184; (* Specific heat capacity of cooling water *)
    rBriquetteUnitMass_kg       : REAL := 0.620; (* Nominal unit mass per pillow briquette *)
    rPocketsPerRev              : REAL := 120.0; (* Circumferential briquette pocket cavities *)
    rProdMassFlow_kg_s          : REAL := 0.0;
    rThermalPower_kW            : REAL := 0.0;
    rWaterEnthalpyGain_kJ_kg    : REAL := 0.0;
    rTargetDeltaT_Water_degC    : REAL := 35.0; (* Permissible non-nucleate boiling temperature rise *)
    rModelWaterFlow_m3h         : REAL := 0.0;
    rQuenchPID_Integral         : REAL := 0.0;
    rQuenchPID_Kp               : REAL := 0.45;
    rQuenchPID_Ki               : REAL := 0.025;

    (* Industrial IEC Timers for Sequences and Watchdogs *)
    tPurgeSettle                : TON;
    tHydPrecharge               : TON;
    tRollSpinUp                 : TON;
    tTiltDeviationTimer         : TON;
    tEmergencyDumpTimer         : TON;
    tFaultDwellTimer            : TON;
END_VAR

(* ========================================================================================= *)
(* STEP 1: SAFETY INTERLOCK VECTORS & EMERGENCY SHUTDOWN MATRIX                             *)
(* ========================================================================================= *)
IF NOT bEStopOk THEN
    (* Immediate hydraulic depressurization to tank, retract roll, cut feeds *)
    rServoValve_A_mA            := 4.0;  (* Servo de-energized to tank return *)
    rServoValve_B_mA            := 4.0;
    rFeedScrewSpeedCmd_rpm      := 0.0;
    rQuenchSprayValve_pct       := 100.0; (* Full deluge flood to prevent fire *)
    rQuenchConveyorSpeed_mpm    := 1.5;  (* Evacuate submerged material slowly *)
    bSystemReady                := FALSE;
    bBriquettingActive          := FALSE;
    bQuenchSprayActive          := TRUE;
    wAlarmCode.0                := TRUE; (* E-Stop Trip *)
    iState                      := 90;   (* Branch to Safe Emergency Retract State *)
END_IF;

IF NOT bN2PurgePermissive AND (iState >= 20) THEN
    (* Inert atmosphere seal compromised: Risk of hydrogen deflagration in quench chamber *)
    wAlarmCode.1                := TRUE; (* N2 Purge / O2 Ingress Fault *)
    bSystemReady                := FALSE;
    iState                      := 90;
END_IF;

(* ========================================================================================= *)
(* STEP 2: TRIPLE MODULAR REDUNDANT (2oo3) TMR SENSOR VALIDATION ENGINE                     *)
(* ========================================================================================= *)
(* Cylinder A 2oo3 Voting & Fault Diagnostics *)
rDiff_A1_A2 := ABS(rHydPress_A1_bar - rHydPress_A2_bar);
rDiff_A2_A3 := ABS(rHydPress_A2_bar - rHydPress_A3_bar);
rDiff_A3_A1 := ABS(rHydPress_A3_bar - rHydPress_A1_bar);

bFail_A1 := (rDiff_A1_A2 > rTMR_Tolerance_bar) AND (rDiff_A3_A1 > rTMR_Tolerance_bar);
bFail_A2 := (rDiff_A1_A2 > rTMR_Tolerance_bar) AND (rDiff_A2_A3 > rTMR_Tolerance_bar);
bFail_A3 := (rDiff_A2_A3 > rTMR_Tolerance_bar) AND (rDiff_A3_A1 > rTMR_Tolerance_bar);

IF NOT bFail_A1 AND NOT bFail_A2 AND NOT bFail_A3 THEN
    (* All three sensors healthy: Median Selection *)
    IF ((rHydPress_A1_bar >= rHydPress_A2_bar) AND (rHydPress_A1_bar <= rHydPress_A3_bar)) OR
       ((rHydPress_A1_bar <= rHydPress_A2_bar) AND (rHydPress_A1_bar >= rHydPress_A3_bar)) THEN
        rVotedPress_A_bar := rHydPress_A1_bar;
    ELSIF ((rHydPress_A2_bar >= rHydPress_A1_bar) AND (rHydPress_A2_bar <= rHydPress_A3_bar)) OR
          ((rHydPress_A2_bar <= rHydPress_A1_bar) AND (rHydPress_A2_bar >= rHydPress_A3_bar)) THEN
        rVotedPress_A_bar := rHydPress_A2_bar;
    ELSE
        rVotedPress_A_bar := rHydPress_A3_bar;
    END_IF;
    wSystemStatusWord.4 := FALSE; (* Cyl A degraded flag cleared *)
ELSIF bFail_A1 AND NOT bFail_A2 AND NOT bFail_A3 THEN
    rVotedPress_A_bar   := (rHydPress_A2_bar + rHydPress_A3_bar) * 0.5;
    wAlarmCode.4        := TRUE; (* Sensor A1 Discrepancy *)
    wSystemStatusWord.4 := TRUE; (* Cyl A operating degraded *)
ELSIF bFail_A2 AND NOT bFail_A1 AND NOT bFail_A3 THEN
    rVotedPress_A_bar   := (rHydPress_A1_bar + rHydPress_A3_bar) * 0.5;
    wAlarmCode.5        := TRUE; (* Sensor A2 Discrepancy *)
    wSystemStatusWord.4 := TRUE;
ELSIF bFail_A3 AND NOT bFail_A1 AND NOT bFail_A2 THEN
    rVotedPress_A_bar   := (rHydPress_A1_bar + rHydPress_A2_bar) * 0.5;
    wAlarmCode.6        := TRUE; (* Sensor A3 Discrepancy *)
    wSystemStatusWord.4 := TRUE;
ELSE
    (* Multiple sensor failure: Fallback to average and flag critical safety alert *)
    rVotedPress_A_bar   := (rHydPress_A1_bar + rHydPress_A2_bar + rHydPress_A3_bar) / 3.0;
    wAlarmCode.7        := TRUE; (* Dual/Triple Sensor Failure on Cylinder A *)
    iDegradedMode       := 1;
END_IF;

(* Cylinder B 2oo3 Voting & Fault Diagnostics *)
rDiff_B1_B2 := ABS(rHydPress_B1_bar - rHydPress_B2_bar);
rDiff_B2_B3 := ABS(rHydPress_B2_bar - rHydPress_B3_bar);
rDiff_B3_B1 := ABS(rHydPress_B3_bar - rHydPress_B1_bar);

bFail_B1 := (rDiff_B1_B2 > rTMR_Tolerance_bar) AND (rDiff_B3_B1 > rTMR_Tolerance_bar);
bFail_B2 := (rDiff_B1_B2 > rTMR_Tolerance_bar) AND (rDiff_B2_B3 > rTMR_Tolerance_bar);
bFail_B3 := (rDiff_B2_B3 > rTMR_Tolerance_bar) AND (rDiff_B3_B1 > rTMR_Tolerance_bar);

IF NOT bFail_B1 AND NOT bFail_B2 AND NOT bFail_B3 THEN
    IF ((rHydPress_B1_bar >= rHydPress_B2_bar) AND (rHydPress_B1_bar <= rHydPress_B3_bar)) OR
       ((rHydPress_B1_bar <= rHydPress_B2_bar) AND (rHydPress_B1_bar >= rHydPress_B3_bar)) THEN
        rVotedPress_B_bar := rHydPress_B1_bar;
    ELSIF ((rHydPress_B2_bar >= rHydPress_B1_bar) AND (rHydPress_B2_bar <= rHydPress_B3_bar)) OR
          ((rHydPress_B2_bar <= rHydPress_B1_bar) AND (rHydPress_B2_bar >= rHydPress_B3_bar)) THEN
        rVotedPress_B_bar := rHydPress_B2_bar;
    ELSE
        rVotedPress_B_bar := rHydPress_B3_bar;
    END_IF;
    wSystemStatusWord.5 := FALSE;
ELSIF bFail_B1 AND NOT bFail_B2 AND NOT bFail_B3 THEN
    rVotedPress_B_bar   := (rHydPress_B2_bar + rHydPress_B3_bar) * 0.5;
    wAlarmCode.8        := TRUE;
    wSystemStatusWord.5 := TRUE;
ELSIF bFail_B2 AND NOT bFail_B1 AND NOT bFail_B3 THEN
    rVotedPress_B_bar   := (rHydPress_B1_bar + rHydPress_B3_bar) * 0.5;
    wAlarmCode.9        := TRUE;
    wSystemStatusWord.5 := TRUE;
ELSIF bFail_B3 AND NOT bFail_B1 AND NOT bFail_B2 THEN
    rVotedPress_B_bar   := (rHydPress_B1_bar + rHydPress_B2_bar) * 0.5;
    wAlarmCode.10       := TRUE;
    wSystemStatusWord.5 := TRUE;
ELSE
    rVotedPress_B_bar   := (rHydPress_B1_bar + rHydPress_B2_bar + rHydPress_B3_bar) / 3.0;
    wAlarmCode.11       := TRUE;
    iDegradedMode       := 2;
END_IF;

(* ========================================================================================= *)
(* STEP 3: DISCRETE SIGNAL FILTERING & TOTAL PHYSICAL FORCE RESOLUTION                      *)
(* ========================================================================================= *)
rFiltPress_A    := (rFilterAlpha * rVotedPress_A_bar) + ((1.0 - rFilterAlpha) * rFiltPress_A);
rFiltPress_B    := (rFilterAlpha * rVotedPress_B_bar) + ((1.0 - rFilterAlpha) * rFiltPress_B);
rFiltGap_A      := (rFilterAlpha * rRollGap_A_mm)     + ((1.0 - rFilterAlpha) * rFiltGap_A);
rFiltGap_B      := (rFilterAlpha * rRollGap_B_mm)     + ((1.0 - rFilterAlpha) * rFiltGap_B);
rFiltHDRI_Temp  := (rFilterAlpha * rHDRI_FeedTemp_degC) + ((1.0 - rFilterAlpha) * rFiltHDRI_Temp);

(* Total Measured Compaction Force [kN]: Sum of Cylinder A and Cylinder B Forces *)
rMeasuredCompactionForce_kN := (rFiltPress_A + rFiltPress_B) * rPressureToForceFactor;

(* Roll Tilt Deviation [mm]: Positive indicates Side A gap wider than Side B *)
rRollTiltDelta_mm := rFiltGap_A - rFiltGap_B;

(* Roll Tilt Protection Interlock *)
tTiltDeviationTimer(IN := (ABS(rRollTiltDelta_mm) > rMaxAllowableTilt_mm), PT := T#150MS);
IF tTiltDeviationTimer.Q THEN
    wAlarmCode.2 := TRUE; (* Critical Angular Tilt / Roll Skew Trip *)
    iState       := 90;
END_IF;

(* ========================================================================================= *)
(* STEP 4: STATE-SPACE MULTI-VARIABLE COUPLING & LQR DECOUPLING CONTROLLER                   *)
(* ========================================================================================= *)
(* Calculate Error Vectors relative to Target Setpoints *)
rMeanGapError   := ((rFiltGap_A + rFiltGap_B) * 0.5) - rTargetRollGap_mm;
rDeltaTiltError := rRollTiltDelta_mm; (* Target tilt is strictly 0.0 mm *)
rMeanForceError := (rForceSetpoint_kN * 0.5) - ((rFiltPress_A + rFiltPress_B) * 0.5 * rPressureToForceFactor);

(* Discrete Observer Update: x_obs(k+1) = A * x_obs(k) + B * u(k) *)
x_obs[1] := (A_mat[1, 1] * rMeanGapError)   + (A_mat[1, 2] * rDeltaTiltError);
x_obs[2] := (A_mat[2, 1] * rMeanGapError)   + (A_mat[2, 2] * rDeltaTiltError);

(* LQR State Feedback Control Effort Calculation *)
rCtrlEffort_Mean  := (K_lqr[1, 1] * x_obs[1]) + (K_lqr[1, 2] * x_obs[2]) + (rMeanForceError * 0.12);
rCtrlEffort_Delta := (K_lqr[2, 1] * x_obs[1]) + (K_lqr[2, 2] * x_obs[2]);

(* Decoupled Hydraulic Pressure Demand per Cylinder [bar] *)
rCmdPress_A_bar := (rForceSetpoint_kN * 0.5 / rPressureToForceFactor) + rCtrlEffort_Mean - (rCtrlEffort_Delta * 0.5);
rCmdPress_B_bar := (rForceSetpoint_kN * 0.5 / rPressureToForceFactor) + rCtrlEffort_Mean + (rCtrlEffort_Delta * 0.5);

(* Clamp Pressure References to Hydraulic Design Envelopes [20.0 .. 315.0 bar] *)
IF rCmdPress_A_bar > 315.0 THEN rCmdPress_A_bar := 315.0; END_IF;
IF rCmdPress_A_bar < 20.0  THEN rCmdPress_A_bar := 20.0;  END_IF;
IF rCmdPress_B_bar > 315.0 THEN rCmdPress_B_bar := 315.0; END_IF;
IF rCmdPress_B_bar < 20.0  THEN rCmdPress_B_bar := 20.0;  END_IF;

(* Convert Pressure Command to Proportional Servo Valve Output (4..20 mA) *)
(* Calibration: 0 bar = 4.0 mA, 350 bar = 20.0 mA *)
rServoValve_A_mA := 4.0 + (rCmdPress_A_bar / 350.0) * 16.0;
rServoValve_B_mA := 4.0 + (rCmdPress_B_bar / 350.0) * 16.0;

(* Servo Output Limiting and Linearity Protection *)
IF rServoValve_A_mA > 20.0 THEN rServoValve_A_mA := 20.0; END_IF;
IF rServoValve_A_mA < 4.0  THEN rServoValve_A_mA := 4.0;  END_IF;
IF rServoValve_B_mA > 20.0 THEN rServoValve_B_mA := 20.0; END_IF;
IF rServoValve_B_mA < 4.0  THEN rServoValve_B_mA := 4.0;  END_IF;

(* ========================================================================================= *)
(* STEP 5: PRE-COMPACTION FEED SCREW ADAPTIVE SPEED SYNCHRONIZATION                         *)
(* ========================================================================================= *)
IF bBriquettingActive AND (rRollSpeedActual_rpm > 1.0) THEN
    (* Anti-reset windup integral trim based on roll compaction force error *)
    rPressErrorIntegral := rPressErrorIntegral + (rMeanForceError * 0.010);
    IF rPressErrorIntegral > 15.0  THEN rPressErrorIntegral := 15.0;  END_IF;
    IF rPressErrorIntegral < -15.0 THEN rPressErrorIntegral := -15.0; END_IF;

    rFeedRatio_Adapted := rFeedRatio_Base + (rKp_Screw * rMeanForceError) + (rKi_Screw * rPressErrorIntegral);
    IF rFeedRatio_Adapted < 1.5 THEN rFeedRatio_Adapted := 1.5; END_IF;
    IF rFeedRatio_Adapted > 5.5 THEN rFeedRatio_Adapted := 5.5; END_IF;

    rFeedScrewSpeedCmd_rpm := rRollSpeedActual_rpm * rFeedRatio_Adapted;
    IF rFeedScrewSpeedCmd_rpm > 95.0 THEN rFeedScrewSpeedCmd_rpm := 95.0; END_IF;
ELSE
    rFeedScrewSpeedCmd_rpm := 0.0;
    rPressErrorIntegral    := 0.0;
END_IF;

(* ========================================================================================= *)
(* STEP 6: ENTHALPY-BASED PRODUCT QUENCH THERMODYNAMICS & WATER SPRAY CONTROL                *)
(* ========================================================================================= *)
(* Production Mass Rate [kg/s] = (Roll RPM / 60) * PocketsPerRev * MassPerPocket *)
rProdMassFlow_kg_s := (rRollSpeedActual_rpm / 60.0) * rPocketsPerRev * rBriquetteUnitMass_kg;

(* Heat Removal Demand [kW]: Q = m_dot * Cp * (T_feed - T_exit_target) *)
IF rFiltHDRI_Temp > rTargetExitTemp_degC THEN
    rThermalPower_kW := rProdMassFlow_kg_s * rCp_Iron_kJ_kgK * (rFiltHDRI_Temp - rTargetExitTemp_degC);
ELSE
    rThermalPower_kW := 0.0;
END_IF;

(* Theoretical Water Mass Flow Required [kg/s] = Q / (Cp_water * DeltaT_water) *)
(* Volume Flow [m3/h] = (MassFlow_kg_s * 3600) / 1000 (rho_water approx 1000 kg/m3) *)
rWaterEnthalpyGain_kJ_kg := rCp_Water_kJ_kgK * rTargetDeltaT_Water_degC;
IF rWaterEnthalpyGain_kJ_kg > 1.0 THEN
    rModelWaterFlow_m3h := (rThermalPower_kW / rWaterEnthalpyGain_kJ_kg) * 3.6;
ELSE
    rModelWaterFlow_m3h := 10.0;
END_IF;

(* Closed-Loop Feedback Trim for Exit Quench Water Temperature *)
rQuenchPID_Integral := rQuenchPID_Integral + ((rQuenchWaterTempIn_degC - 45.0) * 0.01);
IF rQuenchPID_Integral > 25.0  THEN rQuenchPID_Integral := 25.0;  END_IF;
IF rQuenchPID_Integral < -25.0 THEN rQuenchPID_Integral := -25.0; END_IF;

rQuenchSprayValve_pct := (rModelWaterFlow_m3h / 250.0 * 100.0) + (rQuenchPID_Kp * (rQuenchWaterTempIn_degC - 45.0)) + rQuenchPID_Integral;
IF rQuenchSprayValve_pct > 100.0 THEN rQuenchSprayValve_pct := 100.0; END_IF;
IF rQuenchSprayValve_pct < 15.0  THEN rQuenchSprayValve_pct := 15.0;  END_IF; (* Minimum continuous seal curtain flow *)

(* Submerged Quench Apron Conveyor Speed [m/min]: Modulated to ensure adequate water immersion residence time *)
IF rProdMassFlow_kg_s > 0.5 THEN
    rQuenchConveyorSpeed_mpm := 2.0 + (rProdMassFlow_kg_s / 25.0) * 6.5;
    IF rQuenchConveyorSpeed_mpm > 9.0 THEN rQuenchConveyorSpeed_mpm := 9.0; END_IF;
ELSE
    rQuenchConveyorSpeed_mpm := 1.0;
END_IF;

(* ========================================================================================= *)
(* STEP 7: MULTI-STAGE SEQUENTIAL STATE MACHINE                                              *)
(* ========================================================================================= *)
CASE iState OF

    0: (* STATE 0: IDLE / SAFE SYSTEM STANDBY *)
        bSystemReady                := FALSE;
        bBriquettingActive          := FALSE;
        bQuenchSprayActive          := FALSE;
        rServoValve_A_mA            := 4.0;
        rServoValve_B_mA            := 4.0;
        rFeedScrewSpeedCmd_rpm      := 0.0;
        rQuenchSprayValve_pct       := 15.0;
        rQuenchConveyorSpeed_mpm    := 0.0;
        wSystemStatusWord           := 16#0001; (* Idle state bit *)

        IF bEnable AND bEStopOk THEN
            iState := 10;
        END_IF;

    10: (* STATE 10: INERT ATMOSPHERE & N2 SEAL VERIFICATION *)
        wSystemStatusWord := 16#0002;
        tPurgeSettle(IN := bN2PurgePermissive, PT := T#5S);
        IF tPurgeSettle.Q THEN
            tPurgeSettle(IN := FALSE);
            iState := 20;
        ELSIF NOT bN2PurgePermissive THEN
            wAlarmCode.3 := TRUE; (* Purge stabilization timeout *)
        END_IF;

    20: (* STATE 20: HYDRAULIC PRECHARGE & GAP HOMING CALIBRATION *)
        wSystemStatusWord := 16#0004;
        (* Apply initial seating pressure: 60 bar *)
        rServoValve_A_mA := 6.75;
        rServoValve_B_mA := 6.75;
        tHydPrecharge(IN := (rVotedPress_A_bar > 50.0) AND (rVotedPress_B_bar > 50.0), PT := T#3S);
        IF tHydPrecharge.Q THEN
            tHydPrecharge(IN := FALSE);
            IF ABS(rRollTiltDelta_mm) < rWarningTilt_mm THEN
                iState := 30;
            ELSE
                wAlarmCode.12 := TRUE; (* Precharge alignment error *)
            END_IF;
        END_IF;

    30: (* STATE 30: ROLL DRIVE SPIN-UP & QUENCH CIRCUIT INITIATION *)
        wSystemStatusWord  := 16#0008;
        bQuenchSprayActive := TRUE;
        tRollSpinUp(IN := (rRollSpeedActual_rpm > 8.0) AND bBreakerBarRunning, PT := T#4S);
        IF tRollSpinUp.Q THEN
            tRollSpinUp(IN := FALSE);
            bSystemReady := TRUE;
            IF rFiltHDRI_Temp > 550.0 THEN
                iState := 40; (* Ready to receive hot sponge iron *)
            END_IF;
        END_IF;

    40: (* STATE 40: ACTIVE CLOSED-LOOP BRIQUETTING & FORCE SYNCHRONIZATION *)
        wSystemStatusWord  := 16#0010;
        bSystemReady       := TRUE;
        bBriquettingActive := TRUE;
        bQuenchSprayActive := TRUE;

        (* Process boundary checks *)
        IF rFiltHDRI_Temp < 500.0 THEN
            (* Feed material too cold: Risk of pocket compaction jam and roll damage *)
            wAlarmCode.13 := TRUE; (* HDRI Low Temperature Alarm *)
            iState        := 60;   (* Transition to controlled line clearing *)
        END_IF;

        IF NOT bEnable THEN
            iState := 60;
        END_IF;

    50: (* STATE 50: TRANSIENT PROCESS RETRACTION & CHUTE MODULATION *)
        wSystemStatusWord := 16#0020;
        (* Temporarily relieve hydraulic force by 35% during density shock *)
        rServoValve_A_mA := rServoValve_A_mA * 0.65;
        rServoValve_B_mA := rServoValve_B_mA * 0.65;
        rFeedScrewSpeedCmd_rpm := rFeedScrewSpeedCmd_rpm * 0.50;
        IF ABS(rRollTiltDelta_mm) < 0.20 THEN
            iState := 40; (* Return to nominal compaction *)
        END_IF;

    60: (* STATE 60: CONTROLLED SHUTDOWN & MACHINE CLEARING *)
        wSystemStatusWord      := 16#0040;
        bBriquettingActive     := FALSE;
        rFeedScrewSpeedCmd_rpm := 0.0; (* Stop feeding immediately *)
        tFaultDwellTimer(IN := TRUE, PT := T#12S);
        IF tFaultDwellTimer.Q THEN
            tFaultDwellTimer(IN := FALSE);
            iState := 0; (* Return to idle *)
        END_IF;

    90: (* STATE 90: EMERGENCY RETRACT & SAFE INERT FLOOD *)
        wSystemStatusWord        := 16#0080;
        bSystemReady             := FALSE;
        bBriquettingActive       := FALSE;
        rServoValve_A_mA         := 4.0;
        rServoValve_B_mA         := 4.0;
        rFeedScrewSpeedCmd_rpm   := 0.0;
        rQuenchSprayValve_pct    := 100.0;
        rQuenchConveyorSpeed_mpm := 1.5;
        tEmergencyDumpTimer(IN := TRUE, PT := T#8S);
        IF tEmergencyDumpTimer.Q AND bResetFaults AND bEStopOk THEN
            tEmergencyDumpTimer(IN := FALSE);
            wAlarmCode := 16#0000;
            iState     := 0;
        END_IF;

END_CASE;

(* ========================================================================================= *)
(* STEP 8: SYSTEM STATUS & ALARM PACKING                                                     *)
(* ========================================================================================= *)
wSystemStatusWord.0 := (iState = 0);
wSystemStatusWord.1 := (iState = 40);
wSystemStatusWord.2 := bSystemReady;
wSystemStatusWord.3 := bQuenchSprayActive;
wSystemStatusWord.6 := (rQuenchTankLevel_pct > 75.0);
wSystemStatusWord.7 := (rMeasuredCompactionForce_kN > 1000.0);

IF bResetFaults AND (iState <> 90) THEN
    wAlarmCode := 16#0000;
END_IF;

END_FUNCTION_BLOCK
